vectors.spec:
name "ex"
bin "ex"
about "An example"
flag "--shell <SHELL>" help="Which shell" env="EX_SHELL" {
    arg "<SHELL>" default="bash" {
        choices "bash" "zsh"
    }
}
arg "[file]" help="Where to write" default="-"

name "ex"
bin "ex"
flag "-c --config <FILE>" global=#true help="Config file"
cmd "go" help="Go somewhere" {
    flag "--fast" help="Go faster"
}

name "ex"
bin "ex"
about "An example"
flag "--force" help="Do it anyway" {
    long_help "Do it anyway, even when the tool is already installed and the version on disk is the one that was asked for."
}
